// Copies contract ABIs from contracts/out (run `forge build` first) into src/abi as typed constants.
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";

const CONTRACTS = ["Land", "PlayerRegistry"];
const repoRoot = new URL("../../../", import.meta.url);
const abiDir = new URL("packages/shared/src/abi/", repoRoot);
mkdirSync(abiDir, { recursive: true });

const lines = [
  "// GENERATED by `pnpm --filter @linked-realms/shared export-abi`. Do not edit.",
  "",
];
for (const name of CONTRACTS) {
  const artifact = JSON.parse(
    readFileSync(
      new URL(`contracts/out/${name}.sol/${name}.json`, repoRoot),
      "utf8",
    ),
  );
  const constName = `${name[0]!.toLowerCase()}${name.slice(1)}Abi`;
  lines.push(
    `export const ${constName} = ${JSON.stringify(artifact.abi, null, 2)} as const;`,
    "",
  );
}
writeFileSync(new URL("index.ts", abiDir), lines.join("\n"));
console.log(`wrote ${CONTRACTS.length} ABIs to ${abiDir.pathname}`);
